import operator
from numbers import Number

class ParamDict(OrderedDict):
    def __init__(self, *args, **kwargs): super().__init__(*args, *kwargs)
    def _prototype(self, other, op):
        if isinstance(other, Number): return ParamDict({k: op(v, other) for k, v in self.items()})
        elif isinstance(other, dict): return ParamDict({k: op(self[k], other[k]) for k in self})
        else: raise NotImplementedError
    def __add__(self, other): return self._prototype(other, operator.add)
    def __rmul__(self, other): return self._prototype(other, operator.mul); __mul__ = __rmul__
    def __neg__(self): return ParamDict({k: -v for k, v in self.items()})
    def __rsub__(self, other): return self.__add__(other.__neg__()); __sub__ = __rsub__
    def __truediv__(self, other): return self._prototype(other, operator.truediv)

class MovingAverage:
    def __init__(self, ema, oneminusema_correction=True):
        self.ema = ema
        self.ema_data = {}
        self._updates = 0
        self._oneminusema_correction = oneminusema_correction
    def update(self, dict_data):
        ema_dict_data = {}
        for name, data in dict_data.items():
            data = data.view(1, -1)
            if self._updates == 0: previous_data = torch.zeros_like(data)
            else: previous_data = self.ema_data[name]
            ema_data = self.ema * previous_data + (1 - self.ema) * data
            if self._oneminusema_correction: ema_dict_data[name] = ema_data / (1 - self.ema)
            else: ema_dict_data[name] = ema_data
            self.ema_data[name] = ema_data.clone().detach()
        self._updates += 1
        return ema_dict_data

def l2_between_dicts(dict_1, dict_2):
    assert len(dict_1) == len(dict_2)
    dict_1_values = [dict_1[key] for key in sorted(dict_1.keys())]
    dict_2_values = [dict_2[key] for key in sorted(dict_1.keys())]
    return (
        torch.cat(tuple([t.view(-1) for t in dict_1_values])) -
        torch.cat(tuple([t.view(-1) for t in dict_2_values]))
    ).pow(2).mean()

def random_pairs_of_minibatches(minibatches):
    perm = torch.randperm(len(minibatches)).tolist()
    pairs = []
    for i in range(len(minibatches)):
        j = i + 1 if i < (len(minibatches) - 1) else 0
        xi, yi = minibatches[perm[i]][0], minibatches[perm[i]][1]
        xj, yj = minibatches[perm[j]][0], minibatches[perm[j]][1]
        min_n = min(len(xi), len(xj))
        pairs.append(((xi[:min_n], yi[:min_n]), (xj[:min_n], yj[:min_n])))
    return pairs

