def Featurizer(input_shape, hparams):
    if hparams.get('no_featurizer', False): return Identity_Featurizer(input_shape[0], hparams)
    if input_shape is None: return Identity_Featurizer(128, hparams)
    elif len(input_shape) == 1: return MLP(input_shape[0], hparams.get('mlp_width', 256), hparams)
    elif input_shape[1:3] == (28, 28): return MNIST_CNN(input_shape, hparams)
    elif input_shape[1:3] == (224, 224): return ResNet(input_shape, hparams)
    else: return Identity_Featurizer(512, hparams)

def Classifier(in_features, out_features, is_nonlinear=False):
    if is_nonlinear: return torch.nn.Sequential(torch.nn.Linear(in_features, in_features // 2), torch.nn.ReLU(), torch.nn.Linear(in_features // 2, out_features))
    else: return torch.nn.Linear(in_features, out_features)

class WholeFish(nn.Module):
    def __init__(self, input_shape, num_classes, hparams, weights=None):
        super(WholeFish, self).__init__()
        featurizer = Featurizer(input_shape, hparams)
        classifier = Classifier(
            featurizer.n_outputs,
            num_classes,
            hparams.get('nonlinear_classifier', False))
        self.net = nn.Sequential(
            featurizer, classifier
        )
        if weights is not None: self.load_state_dict(copy.deepcopy(weights))
    def reset_weights(self, weights): self.load_state_dict(copy.deepcopy(weights))
    def forward(self, x): return self.net(x)

