class Mixup(ERM):
    def __init__(self, input_shape, num_classes, num_domains, hparams): super(Mixup, self).__init__(input_shape, num_classes, num_domains, hparams)
    def update(self, minibatches, unlabeled=None):
        objective = 0
        for (xi, yi), (xj, yj) in random_pairs_of_minibatches(minibatches):
            lam = np.random.beta(self.hparams["mixup_alpha"], self.hparams["mixup_alpha"])
            x = lam * xi + (1 - lam) * xj
            predictions = self.predict(x)
            objective += lam * F.cross_entropy(predictions, yi)
            objective += (1 - lam) * F.cross_entropy(predictions, yj)
        objective /= len(minibatches)
        self.optimizer.zero_grad(); objective.backward(); self.optimizer.step()
        return {'loss': objective.item()}

class GroupDRO(ERM):
    def __init__(self, input_shape, num_classes, num_domains, hparams): super(GroupDRO, self).__init__(input_shape, num_classes, num_domains, hparams); self.register_buffer("q", torch.Tensor())
    def update(self, minibatches, unlabeled=None):
        device = "cuda" if minibatches[0][0].is_cuda else "cpu"
        if not len(self.q): self.q = torch.ones(len(minibatches)).to(device)
        losses = torch.zeros(len(minibatches)).to(device)
        for m in range(len(minibatches)): losses[m] = F.cross_entropy(self.predict(minibatches[m][0]), minibatches[m][1]); self.q[m] *= (self.hparams["groupdro_eta"] * losses[m].data).exp()
        self.q /= self.q.sum(); loss = torch.dot(losses, self.q)
