class AbstractMMD(ERM):
    def __init__(self, input_shape, num_classes, num_domains, hparams, gaussian): super(AbstractMMD, self).__init__(input_shape, num_classes, num_domains, hparams)
        self.kernel_type = "gaussian" if gaussian else "mean_cov"
    def my_cdist(self, x1, x2):
        x1_norm = x1.pow(2).sum(dim=-1, keepdim=True); x2_norm = x2.pow(2).sum(dim=-1, keepdim=True)
        res = torch.addmm(x2_norm.transpose(-2, -1), x1, x2.transpose(-2, -1), alpha=-2).add_(x1_norm)
        return res.clamp_min_(1e-30)
    def gaussian_kernel(self, x, y, gamma=[0.001, 0.01, 0.1, 1, 10, 100, 1000]):
        D = self.my_cdist(x, y); K = torch.zeros_like(D)
        for g in gamma: K.add_(torch.exp(D.mul(-g)))
        return K
    def mmd(self, x, y):
        if self.kernel_type == "gaussian":
            Kxx = self.gaussian_kernel(x, x).mean(); Kyy = self.gaussian_kernel(y, y).mean(); Kxy = self.gaussian_kernel(x, y).mean()
            return Kxx + Kyy - 2 * Kxy
        else:
            mean_x = x.mean(0, keepdim=True); mean_y = y.mean(0, keepdim=True)
            cent_x = x - mean_x; cent_y = y - mean_y
            cova_x = (cent_x.t() @ cent_x) / (len(x) - 1); cova_y = (cent_y.t() @ cent_y) / (len(y) - 1)
            mean_diff = (mean_x - mean_y).pow(2).mean(); cova_diff = (cova_x - cova_y).pow(2).mean()
            return mean_diff + cova_diff
    def update(self, minibatches, unlabeled=None):
        objective = 0; penalty = 0; nmb = len(minibatches)
        features = [self.featurizer(xi) for xi, _ in minibatches]
        classifs = [self.classifier(fi) for fi in features]
        targets = [yi for _, yi in minibatches]
        for i in range(nmb):
            objective += F.cross_entropy(classifs[i], targets[i])
            for j in range(i + 1, nmb): penalty += self.mmd(features[i], features[j])
        objective /= nmb; penalty = penalty / (nmb * (nmb - 1) / 2) if nmb > 1 else penalty
        self.optimizer.zero_grad(); (objective + (self.hparams['mmd_gamma']*penalty)).backward(); self.optimizer.step()
        return {'loss': objective.item(), 'penalty': penalty.item() if torch.is_tensor(penalty) else penalty}

