# --- `domainbed.datasets` content (MultipleDomainDataset and Toy) ---
class MultipleDomainDataset:
    N_STEPS = 5001; CHECKPOINT_FREQ = 100; N_WORKERS = 4; ENVIRONMENTS = None; INPUT_SHAPE = None
    def __getitem__(self, index): return self.datasets[index]
    def __len__(self): return len(self.datasets)
    def torch_bernoulli_(self, p, size): return (torch.rand(size) < p).float()
    def torch_xor_(self, a, b): return (a - b).abs()

class Toy(MultipleDomainDataset):
    N_STEPS = 30001; ENVIRONMENTS = ['0', '1', '2']; N_WORKERS = 0
    def __init__(self, root, test_envs, hparams):
        super().__init__(); self.test_envs = test_envs; self.hparams = hparams; self.num_classes = 2; self.datasets = []
        self.flip_prob = hparams['flip_prob']; spu_err = hparams['spu_err']; d_causal = hparams['d_causal']; d_spurious = hparams['d_spurious']
        p_correlations = [float(i) for i in spu_err]
        for i, p_correlation in enumerate(p_correlations):
            (x,y,g), n_groups = self.generate_toy_data_complete(n=500, d_causal=d_causal, d_spurious=d_spurious, p_correlation=p_correlation, seed=i, train=True, label_noise=self.flip_prob)
            self.datasets.append(TensorDataset(torch.tensor(x).float(), torch.tensor(y).long()))
        (val_x, val_y, val_g), n_groups = self.generate_toy_data_complete(n=1000, d_causal=d_causal, d_spurious=d_spurious, train=False)
        self.datasets.append(TensorDataset(torch.tensor(val_x).float(), torch.tensor(val_y).long()))
        self.grouped_val_datasets = self.convert_to_dataset_by_groups(val_x, val_y, val_g, n_groups)
        (test_x, test_y, test_g), n_groups = self.generate_toy_data_complete(n=5000, d_causal=d_causal, d_spurious=d_spurious, train=False)
        self.datasets.append(TensorDataset(torch.tensor(test_x).float(), torch.tensor(test_y).long()))
        self.input_shape = test_x.shape[1]
        self.grouped_test_datasets = self.convert_to_dataset_by_groups(test_x, test_y, test_g, n_groups)

    def convert_to_dataset_by_groups(self, x, y, g, n_groups):
        x = torch.tensor(x).float(); y = torch.tensor(y).long(); g = torch.tensor(g).long(); datasets = []
        for i in range(n_groups): indices = torch.nonzero(g == i).squeeze(); datasets.append(TensorDataset(x[indices], y[indices]))
        return datasets

    def generate_toy_data_complete(self, n=1000, d_causal=5, d_spurious=5, p_correlation=0.99, mean_causal=1, var_causal=0.25, mean_spurious=1, var_spurious=0.25, d_noise=2000, noise_type='gaussian', mean_noise=0, var_noise=1, train=True, label_noise=None, seed=None):
        if seed is not None: random.seed(seed); np.random.seed(seed)
        groups = [(1,1), (1,-1), (-1,1), (-1,-1)]; n_groups = len(groups)
        y_list, a_list, x_causal_list, x_spurious_list, g_list = [], [], [], [], []
        processed_n = 0
        for group_idx, (y_value, a_value) in enumerate(groups):
            if group_idx==len(groups)-1: n_group = n - processed_n
            else: n_group = round(n/2*p_correlation) if train and y_value==a_value else round(n/2*(1-p_correlation)) if train else round(n/n_groups)
            processed_n += n_group
            y_list.append(np.ones(n_group)*y_value); a_list.append(np.ones(n_group)*a_value); g_list.append(np.ones(n_group)*group_idx)
            x_causal_list.append(np.random.multivariate_normal(mean=y_value*np.ones(d_causal)*mean_causal, cov=np.eye(d_causal)*var_causal, size=n_group))
            x_spurious_list.append(np.random.multivariate_normal(mean=a_value*np.ones(d_spurious)*mean_spurious, cov=np.eye(d_spurious)*var_spurious, size=n_group))
        x_noise = np.random.multivariate_normal(mean=mean_noise*np.ones(d_noise), cov=np.eye(d_noise)*var_noise/d_noise, size=n) if d_noise>0 else None
        if label_noise is not None and train: y_list = [np.random.choice([-1,1], size=len(y), p=[label_noise, 1-label_noise])*y for y in y_list]
        y = np.concatenate(y_list); a = np.concatenate(a_list); g = np.concatenate(g_list)
        x_causal = np.vstack(x_causal_list); x_spurious = np.vstack(x_spurious_list)
        x = np.hstack([x_causal, x_spurious, x_noise]) if x_noise is not None else np.hstack([x_causal, x_spurious])
        y = [0 if i==-1 else i for i in y]
        return (x, y, g), n_groups
